<script>
export default {
  name: 'MobileApkDialog',
  data () {
    return {
      dontShowAgain: true,
      apkDownloadUrl: 'https://github.com/DesolateSea/Astara_stellarium-web-engine/releases/download/v1.0.0/app-release.apk',
      releasesUrl: 'https://github.com/DesolateSea/Astara_stellarium-web-engine/releases',
      promptTimer: null
    }
  },
  computed: {
    dialogVisible: {
      get () {
        return this.$store.state.showMobileApkDialog
      },
      set (val) {
        this.$store.commit('setValue', { varName: 'showMobileApkDialog', newValue: val })
      }
    },
    isNativeApp () {
      return typeof window !== 'undefined' &&
        window.Capacitor &&
        window.Capacitor.isNativePlatform &&
        window.Capacitor.isNativePlatform()
    },
    isMobileDevice () {
      if (typeof window === 'undefined') return false
      if (this.isNativeApp) return false

      const ua = navigator.userAgent || navigator.vendor || window.opera || ''
      const isMobileUA = /android|iphone|ipad|ipod|blackberry|iemobile|opera mini|mobile/i.test(ua)
      const isTouch = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0)
      const isSmallScreen = window.innerWidth <= 840
      return isMobileUA || (isTouch && isSmallScreen)
    }
  },
  mounted () {
    this.checkAutoPrompt()
  },
  beforeDestroy () {
    if (this.promptTimer) {
      clearTimeout(this.promptTimer)
    }
  },
  methods: {
    checkAutoPrompt () {
      if (this.isMobileDevice && !this.isNativeApp) {
        try {
          const isDismissed = localStorage.getItem('astara_apk_prompt_dismissed')
          if (!isDismissed) {
            // Show prompt after 1.5 seconds for a seamless experience
            this.promptTimer = setTimeout(() => {
              this.dialogVisible = true
            }, 1500)
          }
        } catch (e) {
          console.warn('Could not read from localStorage', e)
        }
      }
    },
    onDownload () {
      try {
        localStorage.setItem('astara_apk_prompt_dismissed', 'true')
      } catch (e) {
        console.warn('Could not save to localStorage', e)
      }
      setTimeout(() => {
        this.dialogVisible = false
      }, 500)
    },
    onDismiss () {
      if (this.dontShowAgain) {
        try {
          localStorage.setItem('astara_apk_prompt_dismissed', 'true')
        } catch (e) {
          console.warn('Could not save to localStorage', e)
        }
      }
      this.dialogVisible = false
    }
  }
}
</script>

